const app = document.querySelector('bulbe-app');
const raiz = document.querySelector('#hu04-raiz');
const voltar = document.querySelector('#hu04-voltar');
function desenhar() {
  const caminho = location.hash.replace(/^#\/?/, '');
  const chave = TELAS[caminho] ? caminho : 'servico';
  const tela = TELAS[chave];
  raiz.innerHTML = tela.html;
  voltar.hidden = !tela.interna;
  app.setAttribute('active-area', 'servico');
  document.title = 'Bulbe | ' + tela.titulo.replace(/^HU04 • /, '');
  document.querySelector('#hu04-telas').innerHTML = '<strong>Telas da HU04</strong>' + Object.entries(TELAS).map(([c, t]) => `<a href="#/${c}"${c === chave ? ' aria-current="page"' : ''}>${t.titulo}</a>`).join('');
  app.shadowRoot?.querySelector('main')?.scrollTo(0, 0);
}

window.addEventListener('hashchange', desenhar);
desenhar();
